# Numeric types
int_var = 42
Int_var = 25
float_var = 3.14
complex_var = 3 + 4j

# Boolean type
bool_var = True

# String type
str_var = "Hello, World!"

# Sequence types
list_var = [1, 2, 3]
tuple_var = (1, 2, 3)
range_var = range(10)

# Mapping type
dict_var = {1: "one", 2: "two", 3: "three"}

# Set types
set_var = {1, 2, 3}
frozenset_var = frozenset({1, 2, 3})

# Binary types
bytes_var = b"hello"
bytearray_var = bytearray(b"hello")
mv_var = memoryview(b"hello")

# Special type
none_var = None
